#!/usr/bin/env python3
"""Serialized API matrix against a new owned synthetic DB; never save KS logs."""
import argparse,hashlib,importlib.util,json,re,shlex,subprocess,time,uuid
from pathlib import Path
HERE=Path(__file__).resolve().parent
OLD=HERE.parent/'patch-tests'
spec=importlib.util.spec_from_file_location('apache_diagnostics',OLD/'collect-api-apache.py')
old=importlib.util.module_from_spec(spec);spec.loader.exec_module(old)
pin_spec=importlib.util.spec_from_file_location('exp11_artifact',HERE/'artifact.py')
pin_module=importlib.util.module_from_spec(pin_spec);pin_spec.loader.exec_module(pin_module)
read_pin=pin_module.read_pin
SSH=['ssh','-T','-F','/tmp/kaltura-php74-ssh.conf','baseline74']
ROOT='/home/vagrant/php-exp11-regression'
HTTP_EXPECTED=[]
for kind in (0,2):
 HTTP_EXPECTED.append(['http-session-start',kind,True])
 for method in ('GET','POST'):HTTP_EXPECTED.append(['http-session-get',kind,method,True])
for label,code in [('missing','SERVICE_FORBIDDEN'),('malformed','INVALID_KS'),('expired','INVALID_KS'),('wrong-secret','START_SESSION_ERROR'),('escalation','START_SESSION_ERROR')]:
 HTTP_EXPECTED.append(['http-rejected',label,code])
EXPECTED_STDOUT=json.dumps(HTTP_EXPECTED)+'\n'+json.dumps(['untrusted-ca-rejected',True])+'\n'+json.dumps(HTTP_EXPECTED)+'\n'


def remote(command,timeout=200):
 return subprocess.run(SSH+[command],capture_output=True,text=True,timeout=timeout)

def api_cases():
 return [("74","original"),("83","original"),("83","exp10"),("83","exp11")]

def main():
 ap=argparse.ArgumentParser();ap.add_argument('output',type=Path);args=ap.parse_args()
 pinned=read_pin()
 if args.output.exists():raise RuntimeError('Refusing to overwrite prior evidence')
 selected={f'api/{n}':HERE/n for n in ['run-apache.sh','start-db.sh','verify-source.py','artifact.py']}
 selected.update({f'tests/{n}':OLD/n for n in ['api-permission-schema.sql','api-session-schema.sql','api-web-router.php','api-apache-inner.sh','api-http-client.py']})
 expected={n:hashlib.sha256(p.read_bytes()).hexdigest() for n,p in selected.items()}
 check=remote('cd '+ROOT+' && sha256sum '+' '.join(expected),30)
 if check.returncode:raise RuntimeError('Fixture hash command failed')
 found={line.split()[1]:line.split()[0] for line in check.stdout.splitlines()}
 if found!=expected:raise RuntimeError('Remote fixture drift')
 verify=remote('python3 '+ROOT+'/api/verify-source.py',60)
 if verify.returncode:raise RuntimeError('Extracted ZIP verification failed')
 artifact=json.loads(verify.stdout)
 if artifact.get('zip_sha256')!=pinned:raise RuntimeError('Current artifact pin mismatch')
 previous=remote('python3 /home/vagrant/php-exp10-regression/api/verify-source.py',60)
 if previous.returncode:raise RuntimeError('exp10 reference source drift')
 previous_artifact=json.loads(previous.stdout)
 token=uuid.uuid4().hex
 db={'datadir':'/tmp/kaltura-pdo-mysql.'+token,'unit':'php83-exp11-api-'+token}
 records=[];cleanup={}
 try:
  start=remote('bash '+ROOT+'/api/start-db.sh '+token,120)
  if start.returncode:raise RuntimeError('Owned synthetic DB startup failed; inspect lab setup log')
  if json.loads(start.stdout)!=db:raise RuntimeError('Unexpected DB identity')
  for runtime,tree in api_cases():
    command='bash '+ROOT+'/api/run-apache.sh '+runtime+' '+tree+' '+shlex.quote(db['datadir'])
    t=time.monotonic_ns();run=remote(command)
    observations=[json.loads(line.split('PROBE_RUNTIME ',1)[1]) for line in run.stderr.splitlines() if 'PROBE_RUNTIME {' in line]
    records.append({'runtime':runtime,'tree':tree,'returncode':run.returncode,'stdout':run.stdout if run.stdout in ('',EXPECTED_STDOUT) else '', 'stdout_whitelisted':run.stdout in ('',EXPECTED_STDOUT),'stdout_sha256':hashlib.sha256(run.stdout.encode()).hexdigest(),'duration_ns':time.monotonic_ns()-t,'diagnostics':old.diagnostics(run.stderr),'runtime_observations':observations,'signature_failure':'Declaration of KalturaPDO::query() must be compatible' in run.stderr,'stderr_sha256':hashlib.sha256(run.stderr.encode()).hexdigest()})
 finally:
  stop=remote('sudo systemctl stop '+shlex.quote(db['unit'])+'; systemctl is-active '+shlex.quote(db['unit']),30)
  cleanup={'unit':db['unit'],'is_active_output':stop.stdout.strip(),'stopped':stop.stdout.strip() in ['inactive','failed','unknown']}
 for verifier,expected_artifact in [(ROOT+'/api/verify-source.py',artifact),('/home/vagrant/php-exp10-regression/api/verify-source.py',previous_artifact)]:
  after=remote('python3 '+verifier,60)
  if after.returncode or json.loads(after.stdout)!=expected_artifact:raise RuntimeError('Post-run artifact drift')
 baseline=next(r for r in records if r['runtime']=='74' and r['tree']=='original')
 comparisons=[{'runtime':r['runtime'],'tree':r['tree'],'matches_baseline':baseline['returncode']==0 and r['returncode']==0 and r['stdout']==baseline['stdout']} for r in records if r['tree'] in ['exp10','exp11']]
 control=next(r for r in records if r['runtime']=='83' and r['tree']=='original')
 passed=baseline['stdout']==EXPECTED_STDOUT and all(r['stdout_whitelisted'] for r in records) and control['returncode']!=0 and control['signature_failure'] and all(r['matches_baseline'] for r in comparisons) and cleanup['stopped']
 report={'schema':1,'scope':'actual exp11 ZIP web/index.php, synthetic SQL, Apache HTTP/trustedHTTPS; NOT AIO/FPM acceptance','artifact':artifact,'previous_artifact':previous_artifact,'harness':expected,'imported_helper_sha256':{n:hashlib.sha256((OLD/n).read_bytes()).hexdigest() for n in ['collect-api-apache.py','collect-api-mysql.py']},'collector_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'db':db,'cleanup':cleanup,'unsupported_cases':[{'runtime':'74','tree':t,'reason':'PHP8.3-only artifact with native mixed return types'} for t in ['exp10','exp11']],'records':records,'comparisons':comparisons,'original83_signature_control':control['signature_failure'],'functional_checks_passed':passed,'application_acceptance':False}
 args.output.write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps({'functional_checks_passed':passed,'comparisons':comparisons,'cleanup':cleanup}))
 return 0 if passed else 1
if __name__=='__main__':raise SystemExit(main())
#!/usr/bin/env python3
"""Fresh baseline74 interpreter/module/library/config hashes, never app execution."""
import argparse
import hashlib
import json
from pathlib import Path
import subprocess
from artifact import read_pin

REMOTE = r'''
import hashlib,json,os,re,socket,subprocess
from pathlib import Path
if socket.gethostname()!='kaltura-php74-baseline' or os.geteuid()!=1000:
 raise RuntimeError('Unexpected lab identity')
def digest(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def run(args):return subprocess.check_output(args,text=True,stderr=subprocess.PIPE,timeout=30)
root=Path('/home/vagrant/php-mysql-probe/runtime83')
php74=Path('/usr/bin/php7.4');php83=root/'php8.3'
modules74=sorted(Path('/usr/lib/php/20190902').glob('*.so'))
modules83=sorted(root.glob('*.so'))
required83=['libphp8.3.so','mysqlnd.so','pdo.so','pdo_mysql.so','posix.so','ctype.so','iconv.so']
if any(not (root/name).is_file() for name in required83):raise RuntimeError('Missing copied runtime module')
apache=[Path('/usr/sbin/apache2')]+[Path('/usr/lib/apache2/modules')/name for name in ['libphp7.4.so','mod_mpm_prefork.so','mod_authz_core.so','mod_alias.so','mod_ssl.so','mod_socache_shmcb.so']]
paths=sorted(set([php74,php83]+modules74+modules83+apache))
identities={str(path):{'sha256':digest(path),'resolved_path':str(path.resolve())} for path in paths}
libraries={}
for path in paths:
 listing=run(['/usr/bin/ldd',str(path)])
 if 'not found' in listing:raise RuntimeError('Missing linked library')
 libraries[str(path)]={p:digest(p) for p in sorted(set(re.findall(r'/[^\s()]+',listing)))}
runtimes={}
for label,path,flags in [('php74-standard',php74,[]),('php74-minimal',php74,['-n']),('php83-minimal',php83,['-n'])]:
 command=[str(path)]+flags
 version=run(command+['-v']);ini=run(command+['--ini']);module_list=run(command+['-m'])
 if not version.startswith('PHP '+('7.4.' if label.startswith('php74') else '8.3.')):raise RuntimeError('Unexpected runtime version')
 config_paths=sorted(set(re.findall(r'(/[^,\s]+\.ini)',ini)))
 if any(not p.startswith('/etc/php/7.4/') for p in config_paths):raise RuntimeError('Unexpected configuration path')
 runtimes[label]={'command':command,'version':version,'ini':ini,'modules':module_list,'configuration_sha256':{p:digest(p) for p in config_paths}}
print(json.dumps({'host':socket.gethostname(),'uid':os.geteuid(),'files':identities,'linked_libraries':libraries,'runtimes':runtimes},sort_keys=True))
'''

def main():
 p=argparse.ArgumentParser();p.add_argument('output',type=Path);a=p.parse_args()
 pinned=read_pin()
 if a.output.exists():raise RuntimeError('Refusing existing runtime identity evidence')
 command=['ssh','-T','-F','/tmp/kaltura-php74-ssh.conf','baseline74','python3 -']
 result=subprocess.run(command,input=REMOTE,capture_output=True,text=True,timeout=150)
 if result.returncode:raise RuntimeError('Runtime identity collection failed; no application was run')
 data=json.loads(result.stdout)
 report={'schema':1,'scope':'fresh baseline74 PHP/Apache modules, linked libraries and INI file hashes; no application-body execution',
         'artifact_pin':pinned,'command':command,'collector_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
         'remote_program_sha256':hashlib.sha256(REMOTE.encode()).hexdigest(),'identity':data,'exit':result.returncode,'stderr_sha256':hashlib.sha256(result.stderr.encode()).hexdigest()}
 a.output.write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps({'files':len(data['files']),'runtime_modes':len(data['runtimes']),'output':str(a.output)}))

if __name__=='__main__':main()
